dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": "kp phenotypes"
    },
    {
      "parameter": "secondPhenotype",
      "label": "Second Phenotype",
      "type": "list",
      "values": "kp phenotypes"
    },
    {
      "parameter": "region",
      "label": "Region by",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000
    },
    {
      "parameter": "csid",
      "label": "Credible Sets ID",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "cvPhenotype",
      "label": "cvPhenotype",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "clump",
      "label": "clump",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Variants",
      "sections": [
        {
          "section": "associations",
          "label": "Associated Variants in Region"
        }
      ]
    },
    {
      "label": "Credible Sets",
      "sections": [
        {
          "section": "credible_sets",
          "label": "Credible Sets in Region"
        },
        {
          "section": "credible_variants",
          "label": "Credible Variants in Region"
        }
      ]
    },
    {
      "label": "Tissue / Annotation",
      "sections": [
        {
          "section": "global_enrichment",
          "label": "Globally Enriched Tissues / Annotations"
        },
        {
          "section": "regions",
          "label": "Enriched Tissues in Region"
        },
        {
          "section": "tissue_regions",
          "label": "Enriched Biosamples in Region"
        }
      ]
    },
    {
      "label": "Gene Links",
      "sections": [
        {
          "section": "gene_links",
          "label": "Gene Links in Enriched Biosamples"
        },
        {
          "section": "variant_links",
          "label": "SNP to Gene Links"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "PhenotypeAncestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": "_"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "PhenotypeAncestry",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard Error",
          "Z Score",
          "Consequence"
        ],
        "tool tips": {
          "Variant ID": "chromosome:position (hg19)_ref/alt",
          "rsID": "Variant ID from dbGaP",
          "Ref/Alt": "Reference allele/alternate allele",
          "P-Value": "Significance of association with the selected phenotype(s)",
          "Beta": "Effect size",
          "MAF": "Minor allele frequency",
          "Z Score": "Beta / Standard error",
          "Consequence": "Impact of the variant for overlapping genes or transcripts, as predicted by the Ensembl Variant Effect Predictor (VEP)",
          "Credible Set": "Posterior Probability of Association for the variant in the selected credible set(s)"
        },
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "LDS",
          "label": "LD score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "filter width": "sm",
      "visualizer": {
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "x axis field": "Position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
    {
      "section id": "credible_sets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "region"
        ],
        "region": "region",
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          }
        ],
        "top rows": [
          "Credible Set ID",
          "PMID",
          "Dataset",
          "Method"
        ],
        "column formatting": {
          "Credible Set ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "credible_variants",
                "label": "View Credible Variants",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      }
    },
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "csid"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true",
        "region": "region"
      },
      "table format": {
        "initial sort by": {
          "field": "Position",
          "type": "number",
          "direction": "asc"
        },
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "Credible Set ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Odds Ratio",
            "raw field": "oddsRatio"
          },
          {
            "type": "raw",
            "field name": "PPA",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "Sample",
            "raw field": "n"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "credible_variants Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "Position",
          "Credible Set ID",
          "Ancestry",
          "PPA",
          "P-Value",
          "Beta",
          "Odds Ratio",
          "EAF",
          "MAF",
          "Z Score",
          "Standard Error",
          "Sample"
        ],
        "star column": "Position",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "PPA": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "visualizer": {
        "type": "region dots track",
        "zoom": "true",
        "render by": "Variant ID",
        "x axis field": "Position",
        "y axis field": "PPA",
        "y axis label": "PPA",
        "hover content": [
          "PPA"
        ],
        "color by": "Credible Set ID",
        "track height": 60,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        }
      }
    },
    {
      "section id": "global_enrichment",
      "header": "Global Enrichment",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "global-enrichment",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Tissue Annotation",
            "fields to join": [
              "tissue",
              "annotation"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "PheAnceAnnoTiss",
            "fields to join": [
              "phenotype",
              "ancestry",
              "annotation",
              "tissue"
            ],
            "join by": [
              "_",
              "_",
              "_"
            ]
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Set Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Expected SNPs",
            "raw field": "expectedSNPs"
          },
          {
            "type": "raw",
            "field name": "SNPs",
            "raw field": "SNPs"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "calculate",
            "field name": "Fold",
            "expression": [
              "SNPs",
              "/",
              "expectedSNPs"
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "Test",
            "expression": [
              "(",
              "SNPs",
              "/",
              "expectedSNPs",
              ")",
              "*",
              "pValue"
            ],
            "calculation type": "math"
          }
        ],
        "top rows": [
          "Tissue",
          "Annotation",
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Expected SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "SNPs": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold": {
            "type": [
              "scientific notation"
            ]
          },
          "Tissue": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Tissue",
                "parameter": [
                  "tissue"
                ]
              }
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "Ancestry",
          "value": "Mixed",
          "type": "search"
        }
      ],
      "visualizer": {
        "type": "scatter plot",
        "render type": "single plot",
        "group by": "Annotation",
        "color by": "Annotation",
        "y axis field": "Fold",
        "y axis label": "Fold (SNPs/expectedSNPs)",
        "x axis field": "P-Value(-log10)",
        "x axis label": "-Log10(p-value)",
        "ticks decimal point": "2",
        "render by": "Tissue",
        "hover content": [
          "Annotation",
          "P-Value",
          "Expected SNPs",
          "SNPs",
          "Fold"
        ],
        "height": 120,
        "width": 200,
        "plot margin": {
          "left": 60,
          "right": 20,
          "top": 40,
          "bottom": 50,
          "bump": 5
        }
      },
      "filters": [
        {
          "field": "Ancestry",
          "label": "Ancestry",
          "type": "checkbox"
        },
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        }
      ]
    },
    {
      "section id": "regions",
      "header": "Regions",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "regions",
        "parameters": [
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "star column": "Position",
        "data convert": [
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region center",
            "expression": [
              "(",
              "start",
              "+",
              "end",
              ")",
              "/",
              2
            ],
            "note": "required to get position"
          },
          {
            "type": "js math",
            "field name": "Position",
            "raw field": "region center",
            "method": "round"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "regions Filter Region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "join multi",
            "field name": "Tissue:Annotation:Region",
            "fields to join": [
              "Tissue",
              "Annotation",
              "Region"
            ],
            "join by": [
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "State",
            "raw field": "state"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          }
        ],
        "top rows": [
          "Tissue",
          "Annotation",
          "Biosample",
          "Region",
          "Method",
          "State",
          "Source",
          "Dataset"
        ],
        "column formatting": {
          "Tissue": {
            "type": [
              "set parameter"
